import { createHash } from "node:crypto";
import { readFile } from "node:fs/promises";
import { describe, expect, it } from "vitest";
import { fingerprintBookFileForKOSync, resolveExactBookFile } from "./phase05.js";

// KOReader v2026.07.1 answers captured by the pinned ProseReader upstream:
// https://github.com/mbret/prose-reader/blob/4c4af604ed03db7486efc596243e464fc0b75cfe/packages/koreader/src/tests/fixtures/koreader-digests.json
// For these short vectors its generated bytes are (offset % 251) + 1.
const cases = [
  [1, "55a54008ad1ba589aa210d2629c1df41"],
  [1023, "fff9361d9ec0d8b26758a55b25798fe4"],
  [1024, "cb5f0affe2bcbda40521890061ddbb0e"],
  [1025, "8e0b01460077afd78b3d57d87b1a3f80"],
  [2048, "8af088f52ab24281a07da920e3bafa29"],
  [4096, "8af088f52ab24281a07da920e3bafa29"],
  [4097, "f6ee46309e04fd7d691c9f7df7ffc0e7"],
  [5121, "aedc9bd794367a689e9083f7f639fb85"],
] as const;

describe("Phase05 KOReader binary digest", () => {
  it("matches KOReader's recorded digest for an actual EPUB fixture", async () => {
    const bytes = await readFile(
      new URL("../../sync/src/fixtures/prose-koreader/synthetic.epub", import.meta.url),
    );
    const identity = await fingerprintBookFileForKOSync({
      bookId: "book_1",
      bookFileId: "file_1",
      relativePath: "synthetic.epub",
      bytes,
    });
    expect(identity.koDocumentHash?.digest).toBe("90bf29d684354cd0c52d028e0505d4be");
  });
  it.each(cases)("matches KOReader's %i-byte golden vector", async (size, expected) => {
    const bytes = Uint8Array.from({ length: size }, (_, offset) => (offset % 251) + 1);
    const identity = await fingerprintBookFileForKOSync({
      bookId: "book_1",
      bookFileId: "file_1",
      relativePath: "books/ไทย.epub",
      bytes,
    });
    expect(identity.koDocumentHash).toEqual({ algorithm: "KO_PARTIAL_MD5", digest: expected });
    expect(identity.fingerprint).toBe(createHash("sha256").update(bytes).digest("hex"));
    expect(identity.entitlementVerified).toBe(false);
  });

  it("fingerprints one snapshot even when the caller modifies its input", async () => {
    const bytes = Uint8Array.from([1, 2, 3, 4]);
    const originalSha = createHash("sha256").update(bytes).digest("hex");
    const pending = fingerprintBookFileForKOSync({
      bookId: "book_1",
      bookFileId: "file_1",
      relativePath: "book.epub",
      bytes,
    });
    bytes.fill(0);
    const identity = await pending;
    expect(identity.fingerprint).toBe(originalSha);
    expect(identity.koDocumentHash?.digest).toBe(
      createHash("md5")
        .update(Uint8Array.from([1, 2, 3, 4]))
        .digest("hex"),
    );
  });

  it("refuses ambiguous partial hashes even when a requested file id is present", async () => {
    const bytes = Uint8Array.from({ length: 2048 }, (_, offset) => (offset % 251) + 1);
    const first = await fingerprintBookFileForKOSync({
      bookId: "book_1",
      bookFileId: "file_1",
      relativePath: "a.epub",
      bytes,
    });
    const other = { ...first, bookFileId: "file_2", relativePath: "b.epub" };
    expect(() =>
      resolveExactBookFile([first, other], {
        koPartialMd5: first.koDocumentHash!.digest,
        expectedSha256: first.fingerprint,
        bookFileId: "file_1",
      }),
    ).toThrow("IDENTITY_MISSING_OR_COLLISION");
  });
});
